import{_ as a,o,c as i,a0 as n}from"./chunks/framework.BGyYNsHo.js";const p=JSON.parse('{"title":"Onda dinámica: ecuaciones de gobierno y algoritmo de solución","description":"","frontmatter":{},"headers":[],"relativePath":"es/explanation/hidraulica/06-solver-de-onda-dinamica.md","filePath":"es/explanation/hidraulica/06-solver-de-onda-dinamica.md"}'),t={name:"es/explanation/hidraulica/06-solver-de-onda-dinamica.md"};function r(c,e,d,s,l,u){return o(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="onda-dinamica-ecuaciones-de-gobierno-y-algoritmo-de-solucion" tabindex="-1">Onda dinámica: ecuaciones de gobierno y algoritmo de solución <a class="header-anchor" href="#onda-dinamica-ecuaciones-de-gobierno-y-algoritmo-de-solucion" aria-label="Permalink to &quot;Onda dinámica: ecuaciones de gobierno y algoritmo de solución&quot;">​</a></h1><h2 id="onda-dinamica-ecuaciones-de-gobierno" tabindex="-1">Onda dinámica: ecuaciones de gobierno <a class="header-anchor" href="#onda-dinamica-ecuaciones-de-gobierno" aria-label="Permalink to &quot;Onda dinámica: ecuaciones de gobierno&quot;">​</a></h2><h3 id="las-ecuaciones-de-st-venant" tabindex="-1">Las ecuaciones de St. Venant <a class="header-anchor" href="#las-ecuaciones-de-st-venant" aria-label="Permalink to &quot;Las ecuaciones de St. Venant&quot;">​</a></h3><p>El modelo de onda dinámica resuelve las ecuaciones unidimensionales completas de de Saint-Venant (continuidad y momentum):</p><p>$$\\underbrace{\\frac{\\partial A}{\\partial t}}<em>{\\text{almacenamiento}} + \\underbrace{\\frac{\\partial Q}{\\partial x}}</em>{\\text{flujo convectivo}} = 0,$$</p><p>$$\\underbrace{\\frac{\\partial Q}{\\partial t}}<em>{\\text{aceleración local}} + \\underbrace{\\frac{\\partial}{\\partial x}!\\left(\\frac{Q^{2}}{A}\\right)}</em>{\\text{aceleración convectiva}} + \\underbrace{gA,\\frac{\\partial H}{\\partial x}}<em>{\\text{gradiente de presión}} + \\underbrace{gA,S_f}</em>{\\text{fricción}} = 0,$$</p><p>donde $A$ es el área hidráulica, $Q$ el caudal, $H = Z + y$ la carga hidráulica ($Z$ cota de batea del conducto, $y$ tirante), $g$ la gravedad y $S_f$ la pendiente de fricción. La pendiente de fricción sigue a Manning:</p><p>$$S_f = \\left(\\frac{n}{1.486}\\right)^{2} \\frac{Q,\\lvert U \\rvert}{A,R^{4/3}}, \\qquad U = \\frac{Q}{A}.$$</p><h3 id="ecuacion-de-momentum-en-diferencias-finitas" tabindex="-1">Ecuación de momentum en diferencias finitas <a class="header-anchor" href="#ecuacion-de-momentum-en-diferencias-finitas" aria-label="Permalink to &quot;Ecuación de momentum en diferencias finitas&quot;">​</a></h3><p>El motor usa una forma implícita (Euler hacia atrás) en diferencias finitas. Con diferencias espaciales sobre la longitud del conducto $L$ y diferencias temporales sobre $\\Delta t$, la actualización de caudal en cada conducto es</p><p>$$Q^{t+\\Delta t} = \\frac{Q^{t} + \\Delta Q_{\\text{inercia}} + \\Delta Q_{\\text{presión}} + \\Delta Q_{\\text{pérdida}}} {1 + \\Delta Q_{\\text{fricción}}},$$</p><p>donde todas las magnitudes geométricas se evalúan en el nuevo tiempo $t + \\Delta t$. Los cuatro términos son:</p><p>$$ \\begin{aligned} \\Delta Q_{\\text{inercia}} &amp;= 2\\bar{U}\\left(\\bar{A}^{t+\\Delta t} - \\bar{A}^{t}\\right) + \\bar{U}^{2},\\frac{A_2 - A_1}{L},\\Delta t, \\ \\Delta Q_{\\text{presión}} &amp;= -g\\bar{A},\\frac{H_2 - H_1}{L},\\Delta t, \\ \\Delta Q_{\\text{fricción}} &amp;= g\\left(\\frac{n}{1.486}\\right)^{2} \\frac{\\lvert \\bar{U} \\rvert}{\\bar{R}^{4/3}},\\Delta t, \\ \\Delta Q_{\\text{pérdida}} &amp;= \\text{pérdidas locales (menores) y términos de evaporación/filtración}. \\end{aligned} $$</p><h3 id="continuidad-en-los-nodos" tabindex="-1">Continuidad en los nodos <a class="header-anchor" href="#continuidad-en-los-nodos" aria-label="Permalink to &quot;Continuidad en los nodos&quot;">​</a></h3><p>La conservación de volumen en cada ensamble de nodo (el nodo más la mitad de cada enlace conectado) requiere</p><p>$$\\frac{\\partial V}{\\partial t} = A_{S},\\frac{\\partial H}{\\partial t} = \\sum Q,$$</p><p>con $A_S = A_{SN} + \\sum A_{SL}$ el área superficial del ensamble (el área superficial propia del nodo más las áreas superficiales de medio enlace que aporta cada conducto). En forma de diferencias finitas:</p><p>$$H^{t+\\Delta t} = H^{t} + \\frac{\\tfrac{\\Delta t}{2}\\left(\\sum Q^{t} + \\sum Q^{t+\\Delta t}\\right)} {\\left(A_{SN} + \\sum A_{SL}\\right)^{t+\\Delta t}},$$</p><p>es decir, una actualización trapezoidal de la carga usando el <em>promedio</em> de los caudales netos en $t$ y $t+\\Delta t$.</p><h2 id="algoritmo-de-solucion-de-la-onda-dinamica" tabindex="-1">Algoritmo de solución de la onda dinámica <a class="header-anchor" href="#algoritmo-de-solucion-de-la-onda-dinamica" aria-label="Permalink to &quot;Algoritmo de solución de la onda dinámica&quot;">​</a></h2><h3 id="resumen-la-iteracion-de-picard-aproximaciones-sucesivas" tabindex="-1">Resumen: la iteración de Picard (aproximaciones sucesivas) <a class="header-anchor" href="#resumen-la-iteracion-de-picard-aproximaciones-sucesivas" aria-label="Permalink to &quot;Resumen: la iteración de Picard (aproximaciones sucesivas)&quot;">​</a></h3><p>La ecuación de momentum (Ecuación 31) y la continuidad de nodo se resuelven implícitamente sobre cada paso de tiempo mediante <em>iteración funcional</em> (iteración de Picard / aproximaciones sucesivas). Los pasos, que coinciden con el <code>DWSolver::execute</code> del motor (<code>DynamicWave.cpp:1026</code>), son:</p><ol><li><strong>initNodeStates</strong> — reinicia los acumuladores por nodo: ingreso = 0, salida = pérdidas $+$ aporte lateral negativo, ingreso $+$ aporte lateral positivo; área superficial desde la geometría de almacenamiento/encharcamiento; convergido = 0, $\\sum dQ/dH = 0$.</li><li><strong>computeLinkGeometry</strong> — calcula en lote los tirantes de extremo $y_1, y_2$, el tirante medio $\\bar y$, los espejos de agua, las áreas y los radios hidráulicos de todos los conductos desde las cargas actuales de los nodos; clasifica el régimen de escurrimiento de cada conducto; aplica las correcciones de ranura de Preissmann donde hay escurrimiento en carga.</li><li><strong>Núcleos de momentum</strong> — resuelve la ecuación de momentum implícita para cada conducto (Sección 9), registra los nuevos caudales y los distribuye en los acumuladores de ingreso/salida de los nodos, acumulando $\\sum dQ/dH$ y las contribuciones de área superficial.</li><li><strong>Estructuras no-conducto</strong> — calcula los caudales de bombas/orificios/vertederos/descargas (Sección 12).</li><li><strong>Niveles de emisario</strong> — vuelve a fijar los niveles de borde de los emisarios desde los caudales actuales.</li><li><strong>Actualización de tirante en los nodos</strong> — resuelve la ecuación de continuidad para la carga de cada nodo (Sección 10); cuenta los nodos no convergidos.</li><li>Si algún nodo cambió más que la tolerancia de carga y no se ha alcanzado el límite de intentos, marca como <em>omitidos (bypassed)</em> los enlaces cuyos dos nodos extremos convergieron (sus caudales se mantienen), e itera.</li></ol><p>Subrelajación: después de la primera iteración, todo caudal y carga actualizados se relajan con $\\omega = 0.5$,</p><p>$$x^{k+1} = (1-\\omega),x^{k} + \\omega,x^{k+1}_{\\mathrm{crudo}}, \\qquad \\omega = 0.5,$$</p><p>y un cambio de signo en el caudal se fuerza a pasar por un valor pequeño no nulo ($q = \\pm 0.001$).</p><h3 id="convergencia" tabindex="-1">Convergencia <a class="header-anchor" href="#convergencia" aria-label="Permalink to &quot;Convergencia&quot;">​</a></h3><p>Un nodo está convergido cuando tanto el residual de Picard crudo como el movimiento aceptado (posiblemente mezclado por Anderson) están dentro de la tolerancia de carga $\\varepsilon_H = 0.005\\ \\mathrm{ft}$ (por defecto). El paso de tránsito converge cuando ningún nodo no-emisario queda sin converger. El número máximo de intentos es 8 por defecto (<code>MAX_TRIALS</code>); un paso que converge en su último intento permitido aún se cuenta como convergido.</p><h3 id="clasificacion-del-escurrimiento" tabindex="-1">Clasificación del escurrimiento <a class="header-anchor" href="#clasificacion-del-escurrimiento" aria-label="Permalink to &quot;Clasificación del escurrimiento&quot;">​</a></h3><p>Durante el cálculo de la geometría, cada conducto se clasifica en una de siete clases de escurrimiento (DRY, UP_DRY, DN_DRY, SUBCRITICAL, SUPERCRITICAL, UP_CRITICAL, DN_CRITICAL) en base a los tirantes de extremo y a la carga relativa a las cotas de batea de los extremos, usando el tirante normal $y_n$ (desde el factor de sección inverso en $Q/\\beta$) y el tirante crítico $y_c$ (Sección 13). La clase determina:</p><ul><li>los ajustes de área superficial para extremos secos/críticos (Tabla 4),</li><li>el tirante usado en el extremo crítico (reemplazado por $\\min(y_n, y_c)$),</li><li>el límite de caudal normal basado en la fricción.</li></ul><table tabindex="0"><thead><tr><th>Condición</th><th>Criterio</th><th>Ajuste</th></tr></thead><tbody><tr><td>Seco aguas arriba</td><td>$y_1 = 0$; $Z_1 &gt; E_1$</td><td>$A_{SL1} = 0$ si $H_2 \\le Z_1$, si no ajuste crítico</td></tr><tr><td>Seco aguas abajo</td><td>$y_2 = 0$; $Z_2 &gt; E_2$</td><td>$A_{SL2} = 0$ si $H_1 \\le Z_2$, si no ajuste crítico</td></tr><tr><td>Crítico aguas arriba</td><td>$Q &lt; 0$; $Z_1 &gt; E_1$; $H_1 - Z_1 &lt; y_*$</td><td>$y_1 = y_*$; $A_{SL1} = 0$</td></tr><tr><td>Crítico aguas abajo</td><td>$Q &gt; 0$; $Z_2 &gt; E_2$; $H_2 - Z_2 &lt; y_*$</td><td>$y_2 = y_*$; $A_{SL2} = 0$</td></tr></tbody></table><p>Ajustes de área superficial y de tirante para extremos de conducto secos/críticos ($y_* = \\min(y_n, y_c)$; $E$ = batea del nodo, $Z$ = batea del conducto).</p><h3 id="contribuciones-de-area-superficial" tabindex="-1">Contribuciones de área superficial <a class="header-anchor" href="#contribuciones-de-area-superficial" aria-label="Permalink to &quot;Contribuciones de área superficial&quot;">​</a></h3><p>Para un conducto subcrítico, las áreas de superficie libre aportadas a sus dos nodos extremos son</p><p>$$A_{SL1} = \\frac{W_1 + \\bar{W}}{2},\\frac{L}{2}, \\qquad A_{SL2} = \\frac{\\bar{W} + W_2}{2},\\frac{L}{2}, \\mathrm{fasnh},$$</p><p>donde $W_1, W_2, \\bar W$ son los espejos de agua en $y_1, y_2, \\bar y$, y $\\mathrm{fasnh}$ es un factor entre el tirante normal y el crítico para un extremo aguas abajo casi crítico. Para extremos secos/críticos el área superficial de medio enlace se ajusta según la Tabla 4; un conducto completamente seco aporta $A_{SL1} = A_{SL2} = \\mathrm{FUDGE}\\cdot L/2$. Un conducto cerrado cuyo tirante medio supera el corte de clave ($y/y_{\\mathrm{full}} \\ge 0.96$ bajo EXTRAN) usa un ancho acotado en la clave en el cálculo del área superficial, entregando la pequeña contribución no nula que mantiene acotado el denominador de Picard del nodo.</p>',37)])])}const $=a(t,[["render",r]]);export{p as __pageData,$ as default};
